// Hand-written pin of the Symbol.for key names Fisi Dock reads from Gentle Shell as of 4.8.0; not source copied from that release.
// Written out by hand on purpose: it must not be generated from Fisi Dock's own expectations.
// Only the opt-in check (FISI_DOCK_CHECK_INSTALLED_GENTLE_SHELL=1) proves a real Gentle Shell still defines them.
export const SIDEBAR_CACHE = Symbol.for("gentle-pi.experimental-sidebar.cache");
export const SIDEBAR_STATE = Symbol.for("gentle-pi.experimental-sidebar.state");
export const ODD_PHASE_REGISTRY = Symbol.for("gentle-pi.odd-phase-registry");
export const PROMPT_OWNER = Symbol.for("gentle-pi.prompt-owner");
